package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Truth gate for Tasha. It is green only when source-bound records, runtimes and reusable GM systems are all present. */
public final class TashaBookClosureEngine{
 private TashaBookClosureEngine(){}
 public static JSONObject report(){JSONObject o=new JSONObject();try{
  TashaCompiledSourceRulesEngine.install();JSONObject spells=TashaSpellRuntimeEngine.install();JSONObject artSubs=TashaArtificerRuntimeEngine.install();JSONObject subs=TashaSubclassRuntimeEngine.install();JSONObject items=TashaItemRuntimeEngine.install();JSONObject artifacts=TashaArtifactRuntimeEngine.install();TashaFeatCompiledRulesEngine.install();JSONObject supplemental=TashaSupplementalRuntimeEngine.install();JSONObject mimic=TashaMimicColonyEngine.installStatblocks();CompiledSupplementProcedureBootstrap.install();
  JSONObject src=TashaCompiledSourceRulesEngine.readiness(),feats=TashaFeatCompiledRulesEngine.readiness(),campaign=TashaCampaignSystemsEngine.descriptor(),world=TashaWorldPhenomenaEngine.descriptor();
  int subExec=CompiledContentMechanicsEngine.countEffectPipelineComplete("subclass"),spellExec=CompiledContentMechanicsEngine.countEffectPipelineComplete("spell"),itemExec=CompiledContentMechanicsEngine.countEffectPipelineComplete("item"),featExec=CompiledContentMechanicsEngine.countEffectPipelineComplete("feat");
  boolean core=subExec>=30&&spellExec>=21&&itemExec>=47&&featExec>=15;
  boolean sup=supplemental.optBoolean("complete",false)&&supplemental.optInt("installed",0)==TashaSupplementalRuntimeEngine.ids().length();
  boolean systems=campaign.optBoolean("persistence_ready",false)&&campaign.optInt("group_patron_types",0)>0&&campaign.optInt("sidekick_classes",0)==3&&campaign.optInt("monster_research_types",0)>0&&world.optBoolean("persistence_ready",false)&&world.optInt("supernatural_region_types",0)>0&&world.optInt("mystic_storm_types",0)>0&&TashaCampaignSystemsEngine.naturalHazardSpellApproximations().length()==23;
  boolean origin=AuthorizedRuleProcedureEngine.has("tasha.origin.asi_reassign")&&AuthorizedRuleProcedureEngine.has("tasha.origin.language_swap")&&AuthorizedRuleProcedureEngine.has("tasha.origin.proficiency_swap")&&AuthorizedRuleProcedureEngine.has("tasha.origin.custom_lineage");
  boolean artifactsOk=artifacts.optBoolean("complete",false)&&artifacts.optInt("installed",0)==6;
  boolean mimicOk=mimic.optInt("installed",0)>=1;
  boolean bootReachable=artifactsOk&&sup;
  boolean complete=src.optBoolean("complete",false)&&core&&sup&&systems&&origin&&artifactsOk&&mimicOk&&bootReachable;
  return o.put("book",TashaCompiledSourceRulesEngine.BOOK).put("subclasses",bucket(subExec,30)).put("spells",bucket(spellExec,21)).put("items",bucket(itemExec,47)).put("feats",bucket(featExec,15)).put("artifacts",bucket(artifacts.optInt("installed",0),6)).put("supplemental_procedures",bucket(supplemental.optInt("installed",0),TashaSupplementalRuntimeEngine.ids().length())).put("artificer_core_and_infusions_in_supplemental",true).put("origin_customization",origin).put("group_patrons",campaign.optInt("group_patron_types",0)).put("sidekick_classes",campaign.optInt("sidekick_classes",0)).put("monster_research_types",campaign.optInt("monster_research_types",0)).put("natural_hazard_spell_mappings",TashaCampaignSystemsEngine.naturalHazardSpellApproximations().length()).put("supernatural_region_types",world.optInt("supernatural_region_types",0)).put("mystic_storm_types",world.optInt("mystic_storm_types",0)).put("world_phenomena_persistence",world.optBoolean("persistence_ready",false)).put("mimic_colony_statblock_runtime",mimicOk).put("source_catalog_complete",src.optBoolean("source_bound_internal_catalog_complete",false)).put("effect_pipeline_complete",src.optBoolean("effect_pipeline_complete",false)).put("auto_rolls",false).put("auto_mutation_allowed",false).put("runtime_boot_wiring",bootReachable).put("tasha_complete",complete).put("status",complete?"TASHA_COMPLETE":"TASHA_INCOMPLETE");
 }catch(Exception e){try{return o.put("tasha_complete",false).put("status","TASHA_GATE_ERROR").put("error",e.getClass().getSimpleName());}catch(Exception ignored){return o;}}}
 private static JSONObject bucket(int actual,int expected)throws Exception{return new JSONObject().put("actual",actual).put("expected",expected).put("complete",actual>=expected);}
}
